//! Shared helpers for the fixture generators: each test renders its fixture files from the command
//! builders and fails if the committed files in `ci/integration/` are out of date.
//!
//! Regenerate all fixtures with `SWAY_THINGS_UPDATE_FIXTURES=1 cargo test -p sway-things-core`.

use std::error::Error;
use std::fs;
use std::path::PathBuf;

pub type Result<T> = std::result::Result<T, Box<dyn Error>>;

/// A new fixture file: the SPDX header and a note that the file is generated by `generator`.
pub fn header(generator: &str) -> String {
    format!(
        "# SPDX-FileCopyrightText: 2026 Sway Things contributors
# SPDX-License-Identifier: GPL-3.0-or-later

# Generated by crates/core/tests/{generator}. DO NOT EDIT.

"
    )
}

pub fn push_line(out: &mut String, line: &str) {
    out.push_str(line);
    out.push('\n');
}

/// Writes the fixtures with `SWAY_THINGS_UPDATE_FIXTURES=1`, otherwise checks that the committed
/// files match.
pub fn check(fixtures: &[(&str, String)]) -> Result<()> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../ci/integration");
    let update = std::env::var_os("SWAY_THINGS_UPDATE_FIXTURES").is_some_and(|value| value == "1");
    for (file, content) in fixtures {
        let path = dir.join(file);
        if update {
            fs::write(&path, content)?;
        } else {
            let committed = fs::read_to_string(&path).unwrap_or_default();
            assert!(
                committed == *content,
                "{} is out of date; regenerate it with SWAY_THINGS_UPDATE_FIXTURES=1 cargo test \
                 -p sway-things-core",
                path.display()
            );
        }
    }
    Ok(())
}
